(globalThis.TURBOPACK||(globalThis.TURBOPACK=[])).push(["object"==typeof document?document.currentScript:void 0,40324,(e,t,s)=>{t.exports=JSON.parse('{"Harness Labs":"Harness Labs","Drills after mastery — not a second install course.":"Des exercices après la maîtrise — pas un second cours d’installation.","Five optional drills after My First AI Agent Part I: rotate a key, break the harness on purpose, measure the empty-session budget, try the Kanban plugin, and run a Bot Mode roster. Not a second install course.":"Cinq exercices optionnels après la Partie I de Mon premier agent IA : faire tourner une clé, casser le harness exprès, mesurer le budget d’une session vide, essayer le plugin Kanban, et monter un roster Bot Mode. Pas un second cours d’installation.","All labs":"Tous les labs","Open Design":"Open Design","After mastery · not a second course":"Après la maîtrise · pas un second cours","Assumes":"On suppose","Requires":"Prérequis","After Part I":"Après la Partie I","After Part II":"Après la Partie II","Advanced":"Avancé","Mastery vs labs":"Maîtrise et labs","Pedagogy lives in My First AI Agent. Labs only drill and produce artifacts.":"La pédagogie est dans Mon premier agent IA. Les labs ne font que l’exercice et l’artefact.","Start mastery Part I":"Commencer la maîtrise, Partie I","My First AI Agent course →":"Cours Mon premier agent IA →","Hermes is already installed and chatting (My First AI Agent Part I). Course default is **Hermes Desktop** from mastery 03 — profile + SOUL exist; several drills open the Desktop cockpit. Labs do not re-teach install, BotFather from zero, or vault setup. CLI-only is fine if you can map the same proofs. If anything is missing, open the mastery modules first.":"Hermes est déjà installé et répond (Mon premier agent IA, Partie I). Le défaut du cours est **Hermes Desktop** depuis la maîtrise 03 — profil + SOUL existent ; plusieurs exercices ouvrent le cockpit Desktop. Les labs ne réenseignent pas l’install, BotFather depuis zéro, ni le coffre. Le CLI seul convient si vous savez retrouver les mêmes preuves. S’il manque quelque chose, ouvrez d’abord les modules de maîtrise.","Three layers":"Trois couches","Labs":"Labs","Mastery":"Maîtrise","Teach · proofs · install first":"Enseigner · preuves · installer d’abord","Drills · artifacts after Part I":"Exercices · artefacts après la Partie I","Curated packages · enable few":"Paquets choisis · n’en activez que peu","Key rotation drill":"Exercice : rotation des clés","You already know what a key is (Harness 01/03). Prove rotation and no secrets in git.":"Vous savez déjà ce qu’est une clé (Harness 01/03). Prouvez la rotation et l’absence de secrets dans git.","Hermes running with at least one provider key":"Hermes tourne avec au moins une clé de fournisseur","You understand .env from mastery; this is audit + rotate practice.":"Vous comprenez .env depuis la maîtrise ; ici c’est l’audit et la rotation.","Harness 03 — Install":"Harness 03 — Installer","keys-audit.md lists providers and secret locations; one key rotated and retested; git status clean of .env.":"keys-audit.md liste les fournisseurs et l’endroit des secrets ; une clé tournée et retestée ; git status sans .env.","Rules (reminder only)":"Règles (rappel seulement)","Secrets only in env / secure store — never SOUL, MEMORY, briefs, or git":"Secrets seulement dans env / coffre — jamais SOUL, MEMORY, briefs, ni git","Rotate on any chat/log leak":"Tournez la clé dès qu’elle fuit dans un chat ou un log","Dev vs prod keys when the provider allows":"Clés dev vs prod quand le fournisseur le permet","If a key hit chat, rotate now. Editing history is not revocation.":"Si une clé a touché le chat, tournez-la maintenant. Éditer l’historique n’est pas une révocation.","Drill":"Exercice","List every provider in keys-audit.md with where the secret lives.":"Listez chaque fournisseur dans keys-audit.md avec l’endroit du secret.","Move any secret that lives in a markdown note into env; rotate that key.":"Déplacez tout secret qui vit dans une note markdown vers env ; tournez cette clé.","Rotate the least-critical key on purpose; update Hermes; one successful chat.":"Tournez exprès la clé la moins critique ; mettez Hermes à jour ; un chat qui marche.","Confirm .env is gitignored in repos Hermes can write; git status.":"Confirmez que .env est gitignored dans les repos où Hermes peut écrire ; git status.","Failure studio":"Atelier des pannes","Break it on purpose: doctor, logs, stuck approvals, bad tool loops — then fix.":"Cassez exprès : doctor, logs, approbations coincées, boucles d’outils — puis réparez.","My First AI Agent Part I (Hermes chats; gateway optional)":"Mon premier agent IA Partie I (chats Hermes ; gateway optionnel)","Desktop or CLI install works on a good day; you have not turned YOLO on for the course.":"L’install Desktop ou CLI marche un jour sans nuage ; vous n’avez pas activé YOLO pour le cours.","failure-log.md with three forced failures, what you saw (logs/UI), and the fix for each. No secrets pasted.":"failure-log.md avec trois pannes forcées, ce que vous avez vu (logs/UI), et la réparation de chacune. Aucun secret collé.","Why this lab exists":"Pourquoi ce lab existe","Mastery teaches the happy path. Production is the unhappy path: wrong key, hung approval, agent looping tools, gateway silent. This lab forces three failures so doctor and logs become muscle memory — not panic search.":"La maîtrise enseigne le chemin heureux. La production est le chemin malheureux : mauvaise clé, approbation coincée, agent qui boucle les outils, gateway muet. Ce lab force trois pannes pour que doctor et logs deviennent un réflexe — pas une recherche en panique.","Harness 10 — Security dials":"Harness 10 — Curseurs de sécurité","Harness 06 — First agency":"Harness 06 — Première agence","Do this on a non-production profile if you have one.":"Faites-le sur un profil hors production si vous en avez un.","Never paste API keys or bot tokens into failure-log.md.":"Ne collez jamais de clés API ni de tokens de bot dans failure-log.md.","Do not open WAN ports or disable allowlist “to reproduce.”":"N’ouvrez pas de ports WAN et ne désactivez pas l’allowlist « pour reproduire ».","Stop if you are about to run destructive shell on real data — use a throwaway folder.":"Arrêtez-vous si vous allez lancer un shell destructeur sur de vraies données — utilisez un dossier jetable.","Goal is observability, not bricking the host. If chat dies completely, reinstall path is mastery 03 — not this lab.":"Le but est l’observabilité, pas de brique l’hôte. Si le chat meurt tout à fait, le chemin de réinstall est la maîtrise 03 — pas ce lab.","Failure A — provider / auth smoke":"Panne A — fumée fournisseur / auth","With Hermes working, temporarily break model auth (wrong key in a throwaway env, or disable the active provider in UI). Do not commit the bad key.":"Hermes marchant, cassez temporairement l’auth du modèle (mauvaise clé dans un env jetable, ou fournisseur actif désactivé dans l’UI). Ne commitez pas la mauvaise clé.","Send a one-line chat. Capture the error surface (UI message or hermes logs snippet redacted).":"Envoyez un chat d’une ligne. Capturez la surface d’erreur (message UI ou extrait de hermes logs, caviardé).","Run hermes doctor (or Desktop health) if available. Note what it caught vs what it missed.":"Lancez hermes doctor (ou la santé Desktop) s’il est là. Notez ce qu’il a vu et ce qu’il a manqué.","Restore the good key. Confirm chat works. Log A in failure-log.md.":"Restaurez la bonne clé. Confirmez que le chat marche. Notez A dans failure-log.md.","Failure B — approval stuck":"Panne B — approbation coincée","Set approvals to manual (or ensure a dangerous tool will prompt).":"Mettez les approbations en manuel (ou assurez-vous qu’un outil dangereux demandera).","Ask for a tool action that needs approval. Leave it unanswered for 30–60s (or until timeout if shorter).":"Demandez une action d’outil qui nécessite une approbation. Laissez sans réponse 30–60 s (ou jusqu’au timeout s’il est plus court).","Note timeout / deny behavior. Approve or cancel deliberately.":"Notez le timeout / le refus. Approuvez ou annulez exprès.","Log B: approval mode, what the UI showed, final outcome.":"Notez B : mode d’approbation, ce que l’UI a montré, résultat final.","Failure C — tool thrash / bad path":"Panne C — outils en boucle / mauvais chemin","Ask the agent to write a file to a path that does not exist or is outside the allowed workspace (safe denial expected).":"Demandez à l’agent d’écrire un fichier vers un chemin qui n’existe pas ou hors de l’espace autorisé (refus attendu).","If it loops retries, stop the run after 2–3 cycles. Prefer “stop / cancel” over force-kill unless hung.":"S’il retente en boucle, arrêtez après 2–3 cycles. Préférez « stop / cancel » au kill forcé, sauf si c’est figé.","Find logs or session transcript. Redact paths if sensitive. Note how you stopped the loop.":"Trouvez les logs ou la transcription. Caviarder les chemins s’ils sont sensibles. Notez comment vous avez arrêté la boucle.","Log C with one sentence on how you will scope tools next time.":"Notez C en une phrase sur le périmètre des outils la prochaine fois.","failure-log.md template":"Modèle failure-log.md","Prompt budget audit":"Audit du budget de prompt","Measure fixed empty-session cost; cut tools and skills; re-measure.":"Mesurez le coût fixe d’une session vide ; coupez outils et skills ; re-mesurez.","My First AI Agent 06; better after 09 skills":"Mon premier agent IA 06 ; mieux après 09 skills","Primary model works. You can open Tools and Skills panels (or CLI hermes tools / hermes skills).":"Le modèle principal marche. Vous savez ouvrir les panneaux Tools et Skills (ou CLI hermes tools / hermes skills).","prompt-budget.md with before/after prompt-size (or Desktop audit) and two concrete cuts (toolset and/or skill).":"prompt-budget.md avec le prompt-size avant/après (ou audit Desktop) et deux coupes concrètes (toolset et/ou skill).","Why this lab":"Pourquoi ce lab","Empty sessions still load system prompt, skills index, memory snapshots, tool schemas, and AGENTS.md. Upgrading the model will not fix a bloated fixed budget. This lab measures and cuts.":"Une session vide charge encore le prompt système, l’index des skills, des instantanés de mémoire, les schémas d’outils, et AGENTS.md. Changer de modèle ne répare pas un budget fixe gonflé. Ce lab mesure et coupe.","Harness 06 — Spend / fixed cost":"Harness 06 — Dépense / coût fixe","Harness 09 — Skills":"Harness 09 — Skills","Audit":"Audit","Run hermes prompt-size (offline OK) or the Desktop prompt-budget / context audit if labeled differently. Record total and top slices in prompt-budget.md.":"Lancez hermes prompt-size (hors-ligne OK) ou l’audit budget / contexte Desktop s’il a un autre nom. Notez le total et les plus gros morceaux dans prompt-budget.md.","List enabled toolsets. Disable one you never use for this profile (hermes tools or Desktop Tools).":"Listez les toolsets actifs. Désactivez-en un que ce profil n’utilise jamais (hermes tools ou Desktop Tools).","List skills. Uninstall or disable one “for later” skill.":"Listez les skills. Désinstallez ou désactivez une skill « pour plus tard ».","Re-run the audit. Write before → after numbers.":"Relancez l’audit. Écrivez les chiffres avant → après.","One-line chat: confirm the agent still works for a simple task.":"Un chat d’une ligne : confirmez que l’agent marche encore pour une tâche simple.","Do not delete SOUL or MEMORY to win the audit. Cut unused tools and skills first.":"Ne supprimez pas SOUL ni MEMORY pour gagner l’audit. Coupez d’abord les outils et skills inutiles.","prompt-budget.md template":"Modèle prompt-budget.md","Kanban multi-profile":"Kanban multi-profil","Enable the official Desktop Kanban plugin; run one card across profiles.":"Activez le plugin Kanban officiel du Desktop ; faites passer une carte entre profils.","My First AI Agent Part I; two profiles with SOUL optional but recommended":"Mon premier agent IA Partie I ; deux profils, SOUL optionnel mais recommandé","Desktop chat works on at least one profile. You are not installing Hermes here.":"Le chat Desktop marche sur au moins un profil. Vous n’installez pas Hermes ici.","Harness 04 — Soul pack":"Harness 04 — Pack d’âme","kanban-notes.md: plugin enabled, one card moved through columns, which profile ran which step, screenshot optional (no secrets).":"kanban-notes.md : plugin activé, une carte déplacée dans les colonnes, quel profil a fait quelle étape, capture optionnelle (sans secrets).","Kanban is the first official Hermes Desktop plugin: board UI, sidebar, hotkeys, backend. It is multi-step / multi-profile work — growth after a solid single harness, not Part I.":"Kanban est le premier plugin officiel Hermes Desktop : tableau, barre, raccourcis, backend. C’est du travail multi-étapes / multi-profils — de la croissance après un harness solide, pas la Partie I.","The Kanban board in use. Video plays on X.":"Le tableau Kanban en usage. La vidéo se joue sur X.","Harness 12 — Own it forever":"Harness 12 — Le posséder pour de bon","Desktop plugin SDK":"Desktop plugin SDK","Enable and run":"Activer et faire tourner","In Desktop, open Plugins (or Extensions). Enable Kanban if not already on. Restart Desktop if required.":"Dans Desktop, ouvrez Plugins (ou Extensions). Activez Kanban s’il n’est pas déjà là. Redémarrez Desktop si besoin.","Confirm a Kanban page or sidebar entry appears.":"Confirmez qu’une page Kanban ou une entrée de barre apparaît.","Create one real-ish task card (e.g. “Draft weekly notes outline”). Keep scope small.":"Créez une carte de tâche à peu près réelle (ex. « Plan des notes de la semaine »). Gardez le périmètre petit.","If you have two profiles: assign steps so each profile handles a different stage (research vs draft). If one profile only: run the board end-to-end on that profile and note “single profile” in kanban-notes.md.":"Si vous avez deux profils : assignez les étapes pour que chacun prenne un stade (recherche vs brouillon). Un seul profil : faites le tableau de bout en bout et notez « profil unique » dans kanban-notes.md.","Move the card through at least two columns. Capture which agent/profile acted.":"Faites passer la carte dans au moins deux colonnes. Notez quel agent/profil a agi.","Write kanban-notes.md: enable path, columns used, profile map, one friction note.":"Écrivez kanban-notes.md : chemin d’activation, colonnes, carte des profils, une friction.","Do not open the board to untrusted users. Same allowlist discipline as gateway. Plugins extend trust surface.":"N’ouvrez pas le tableau à des utilisateurs non fiables. Même discipline d’allowlist que le gateway. Les plugins agrandissent la surface de confiance.","kanban-notes.md template":"Modèle kanban-notes.md","Bot Mode roster":"Roster Bot Mode","Turn two souls into named Bots, give each a harness, run one @mention handoff, and keep a file receipt.":"Transformez deux âmes en Bots nommés, donnez à chacun un harness, faites une passation @mention, et gardez un reçu fichier.","My First AI Agent Part I; Desktop with a Bots tab (on by default in current builds). Souls from Harness 04.":"Mon premier agent IA Partie I ; Desktop avec un onglet Bots (activé par défaut dans les builds actuels). Âmes de Harness 04.","Desktop chat already works. You have pasted a soul into a profile. Bot Mode is the Bots tab next to Sessions — not a second Hermes install.":"Le chat Desktop marche déjà. Vous avez collé une âme dans un profil. Bot Mode est l’onglet Bots à côté de Sessions — pas une seconde install Hermes.","bot-roster.md names two Bots and their harness (soul, model, skills, tools, memory, face); one @mention handoff produced briefing.md you can open offline.":"bot-roster.md nomme deux Bots et leur harness (âme, modèle, skills, outils, mémoire, visage) ; une passation @mention a produit briefing.md que vous ouvrez hors-ligne.","You can say, in plain words: a Bot is a named profile; each specialist gets a harness (soul, model, tools); @mentions are fire-and-forget; you stay the operator. `bot-roster.md` names two Bots; `briefing.md` opens offline.":"Vous pouvez dire, en mots simples : un Bot est un profil nommé ; chaque spécialiste a un harness (âme, modèle, outils) ; les @mentions sont en fire-and-forget ; vous restez l’opérateur. `bot-roster.md` nomme deux Bots ; `briefing.md` s’ouvre hors-ligne.","How to read this lab":"Comment lire ce lab","This is a **drill**, not a thirteenth lesson. You already have a profile and a soul (Harness 04). Read the four cards, then do Drill A and Drill B. Group chat and the stretch are extra.":"C’est un **exercice**, pas une treizième leçon. Vous avez déjà un profil et une âme (Harness 04). Lisez les quatre cartes, puis faites l’exercice A et l’exercice B. Le chat de groupe et l’extension sont en plus.","Come back to a card when Desktop names that word (Bots tab, @mention, group).":"Revenez à une carte quand Desktop nomme ce mot (onglet Bots, @mention, groupe).","Proof is a file you open offline — chat alone is not the receipt.":"La preuve est un fichier que vous ouvrez hors-ligne — le chat seul n’est pas le reçu.","Harness 04 taught one profile, one soul. Bot Mode is the Desktop roster for those same profiles: a name, a face, a pinned model, isolated memory, and a way for Bots to pass work with @mentions. Build a specialist once; it is still there next week.":"Harness 04 a enseigné un profil, une âme. Bot Mode est le roster Desktop de ces mêmes profils : un nom, un visage, un modèle épinglé, une mémoire isolée, et un moyen pour les Bots de se passer le travail avec des @mentions. Construisez un spécialiste une fois ; il est encore là la semaine suivante.","This is not a marketing department and not a second product. You stay the operator. Delivery between Bots is fire-and-forget: the teammate answers in its own Bot Chat when it next runs.":"Ce n’est pas un service marketing et pas un second produit. Vous restez l’opérateur. La livraison entre Bots est en fire-and-forget : le coéquipier répond dans son propre Bot Chat quand il tourne ensuite.","Bot Mode docs: create, harness, avatars, routines, group chats, @mentions. Video plays on X.":"Docs Bot Mode : créer, harness, avatars, routines, chats de groupe, @mentions. La vidéo se joue sur X.","Official Bot Mode docs":"Docs officielles Bot Mode","Lab: Kanban multi-profile":"Lab : Kanban multi-profil","Core words":"Mots du socle","Four lines name almost everything in this drill. The rest is how you click it.":"Quatre lignes nomment presque tout dans cet exercice. Le reste est comment vous cliquez.","Bot":"Bot","A named Hermes profile in the Desktop roster: own soul, model, memory, skills, and chat. Files still live under `~/.hermes/profiles/<name>/`.":"Un profil Hermes nommé dans le roster Desktop : propre âme, modèle, mémoire, skills et chat. Les fichiers vivent toujours sous `~/.hermes/profiles/<name>/`.","Bot = named profile. Not a Telegram gateway. Not a new product.":"Bot = profil nommé. Pas une passerelle Telegram. Pas un nouveau produit.","Harness (per Bot)":"Harness (par Bot)","The six knobs this specialist is allowed: soul, model pin, skills, tools, memory, face. Shared notes are the company brain; MEMORY.md stays per Bot.":"Les six boutons autorisés à ce spécialiste : âme, modèle épinglé, skills, outils, mémoire, visage. Les notes partagées sont le cerveau de l’entreprise ; MEMORY.md reste par Bot.","Least tools per Bot. Writer without web if researcher fetches.":"Le moins d’outils par Bot. Le rédacteur sans web si le chercheur va chercher.","Canonical Bot Chat":"Bot Chat canonique","The forever-chat created when the Bot is born. `/new` there compacts context; it does not fork a new relationship.":"Le chat pour toujours, créé à la naissance du Bot. `/new` y compacte le contexte ; il ne fourche pas une nouvelle relation.","One Bot, one canonical chat.":"Un Bot, un chat canonique.","@mention / handoff":"@mention / passation","Type `@researcher have a look`. The sending Bot composes its own message. Delivery is fire-and-forget: the reply lands later in the teammate’s Bot Chat.":"Tapez `@researcher have a look`. Le Bot qui envoie compose son propre message. La livraison est en fire-and-forget : la réponse arrive plus tard dans le Bot Chat du coéquipier.","Handoff, not a live interrupt. You stay the operator.":"Une passation, pas une interruption en direct. Vous restez l’opérateur.","A Bot is a profile":"Un Bot est un profil","There is no new primitive. The Bots tab is a UI over profiles you already made. CLI parity: `hermes -p researcher chat` is the same agent. If you ran the Kanban lab, those profiles are already Bots — give them faces and a handoff.":"Il n’y a pas de nouvelle primitive. L’onglet Bots est une interface sur les profils que vous avez déjà faits. Parité CLI : `hermes -p researcher chat` est le même agent. Si vous avez fait le lab Kanban, ces profils sont déjà des Bots — donnez-leur un visage et une passation.","**New Agent** is three fields (Name, Title, Description). Advanced opens clone, model pin, SOUL.md, and per-skill / per-toolset ticks.":"**New Agent** tient en trois champs (Name, Title, Description). Advanced ouvre le clone, l’épingle de modèle, SOUL.md, et les cases par skill / toolset.","Routines are ordinary cron jobs named `[bot:<name>] …` — they also show in `hermes cron list`.":"Les routines sont des jobs cron ordinaires nommés `[bot:<name>] …` — elles apparaissent aussi dans `hermes cron list`.","If the Bots tab is missing: Settings → Plugins → Bots, then a current Desktop build. The old standalone plugin repo is archived.":"Si l’onglet Bots manque : Settings → Plugins → Bots, puis un build Desktop actuel. L’ancien dépôt de plugin autonome est archivé.","Hide a Bot you are not using (right-click → Hide Bot). Delete only when sure. The default profile cannot be deleted.":"Masquez un Bot dont vous ne vous servez pas (clic droit → Hide Bot). Ne supprimez que si vous êtes sûr. Le profil default ne se supprime pas.","The harness (six knobs)":"Le harness (six boutons)","Packaging is cheap. The moat is what you put in: soul, examples of good, voice rules, and which tools this specialist may touch. Do not clone a seven-Bot “team” on day one.":"L’emballage est bon marché. Le fossé, c’est ce que vous y mettez : âme, exemples de ce qui est bon, règles de voix, et quels outils ce spécialiste a le droit de toucher. Ne clonez pas une « équipe » de sept Bots le premier jour.","Knob":"Bouton","What you set":"Ce que vous réglez","This lab":"Ce lab","Role":"Rôle","SOUL.md — identity, style, avoid, defaults, hard limits":"SOUL.md — identité, style, à éviter, défauts, limites dures","Analyst (Iris) / Writer (Quill)":"Analyst (Iris) / Writer (Quill)","Model":"Modèle","Pin cheap/fast for throughput; stronger for draft. Inherit if one provider.":"Épinglez bon marché/rapide pour le débit ; plus fort pour le brouillon. Héritez s’il n’y a qu’un fournisseur.","Pin if you can; else inherit":"Épinglez si vous pouvez ; sinon héritez","Skills":"Skills","Only the howtos this specialist runs":"Seulement les howtos que ce spécialiste exécute","Skip bundled noise":"Sautez le bruit fourni d’office","Tools":"Outils","Least privilege":"Le moins de privilège","Researcher: web. Writer: no fetch":"Chercheur : web. Rédacteur : pas de fetch","Memory":"Mémoire","What this Bot remembers across jobs":"Ce que ce Bot retient d’un job à l’autre","Not secrets in SOUL":"Pas de secrets dans SOUL","Face":"Visage","Blob / geometric / upload / AI portrait / pixel pet":"Blob / géométrique / import / portrait IA / pixel pet","Pick one each":"Un chacun","One Bot per vertical, each with its own harness — start with two, not seven.":"Un Bot par verticale, chacun avec son harness — commencez par deux, pas sept.","One job per Bot, then a handoff. Tighten from there.":"Un job par Bot, puis une passation. Serrez à partir de là.","Safety rules":"Règles de sécurité","Approvals stay **manual**. Do not turn YOLO on for this lab.":"Les approbations restent **manuelles**. N’activez pas YOLO pour ce lab.","Least tools. A writer with web fetch will invent a research job.":"Le moins d’outils. Un rédacteur avec fetch web s’inventera un job de recherche.","No secrets in SOUL, MEMORY, `briefing.md`, or `bot-roster.md`. Shared OAuth is the default — do not paste keys to “give a Bot access.”":"Pas de secrets dans SOUL, MEMORY, `briefing.md`, ni `bot-roster.md`. L’OAuth partagé est le défaut — ne collez pas de clés pour « donner accès à un Bot ».","Group chats cap at 2–6 Bots and three serial rounds. If a Bot `@user`s you, that is a judgment call — answer or stop.":"Les chats de groupe plafonnent à 2–6 Bots et trois tours en série. Si un Bot vous `@user`, c’est un appel au jugement — répondez ou arrêtez.","You are still the operator. A roster with @mentions is a handoff protocol, not a department that runs while you sleep.":"Vous restez l’opérateur. Un roster avec des @mentions est un protocole de passation, pas un service qui tourne pendant que vous dormez.","Drill A — hire two specialists":"Exercice A — embaucher deux spécialistes","Open Hermes Desktop. Confirm a **Bots** tab next to Sessions. If missing: Settings → Plugins → Bots, restart.":"Ouvrez Hermes Desktop. Confirmez un onglet **Bots** à côté de Sessions. S’il manque : Settings → Plugins → Bots, redémarrez.","New Agent: name `researcher`, title Research analyst, description “Sourced bullets only. Label speculation. Never invent citations.”":"New Agent : name `researcher`, title Research analyst, description « Puces sourcées seulement. Étiquetez la spéculation. N’inventez jamais de citations. »","Advanced: paste the Analyst (Iris) soul from Harness 04. Enable only the web/search tools this Bot needs.":"Advanced : collez l’âme Analyst (Iris) de Harness 04. N’activez que les outils web/search dont ce Bot a besoin.","Give it a blob or geometric face. Pin a cheap/fast model if you have a second provider; otherwise inherit.":"Donnez-lui un visage blob ou géométrique. Épinglez un modèle bon marché/rapide si vous avez un second fournisseur ; sinon héritez.","New Agent: name `writer`, title Drafting specialist. Paste the Writer (Quill) soul. **Disable web fetch.** Pin a stronger model if you have one.":"New Agent : name `writer`, title Drafting specialist. Collez l’âme Writer (Quill). **Désactivez le fetch web.** Épinglez un modèle plus fort si vous en avez un.","Open each Bot Chat. Ask: “Who are you and what are your hard limits?” Confirm they answer in that soul.":"Ouvrez chaque Bot Chat. Demandez : « Qui es-tu et quelles sont tes limites dures ? » Confirmez qu’ils répondent dans cette âme.","Drill B — one @mention handoff":"Exercice B — une passation @mention","Pick one real topic you already care about (a book, a local issue, a product you use). Write it in `bot-roster.md`.":"Choisissez un vrai sujet qui vous concerne déjà (un livre, un enjeu local, un produit que vous utilisez). Écrivez-le dans `bot-roster.md`.","In the writer Bot Chat, type: `@researcher five sourced bullets on [topic]. No invented citations.` Wait — the reply is not instant.":"Dans le Bot Chat du rédacteur, tapez : `@researcher five sourced bullets on [topic]. No invented citations.` Attendez — la réponse n’est pas instantanée.","When the bullets land: `@writer 150–200 words in my voice from those bullets. Flag unsourced claims. Write briefing.md in my notes folder. Do not send.`":"Quand les puces arrivent : `@writer 150–200 words in my voice from those bullets. Flag unsourced claims. Write briefing.md in my notes folder. Do not send.`","Open `briefing.md` offline. If it exists only inside the chat, ask writer to write the file with an absolute path you control.":"Ouvrez `briefing.md` hors-ligne. S’il n’existe que dans le chat, demandez au rédacteur d’écrire le fichier avec un chemin absolu que vous contrôlez.","In `bot-roster.md`, record: who spoke, which chat the reply appeared in, and whether there was a delay (fire-and-forget is expected).":"Dans `bot-roster.md`, notez : qui a parlé, dans quel chat la réponse est apparue, et s’il y a eu un délai (le fire-and-forget est attendu).","The composer’s `@` autocomplete resolves against the live roster. Your text is not forwarded verbatim. An unknown `@` (or an email) passes through untouched.":"L’autocomplétion `@` du compositeur résout contre le roster live. Votre texte n’est pas transféré tel quel. Un `@` inconnu (ou un e-mail) passe intact.","Drill C — group chat":"Exercice C — chat de groupe","Right-click a local Bot → Manage groups (or New Group Chat). Seat only `researcher` and `writer`.":"Clic droit sur un Bot local → Manage groups (ou New Group Chat). Asseyez seulement `researcher` et `writer`.","Open the room. Send one message that mentions both: `@researcher` check the bullets still match the sources; `@writer` keep the brief under 200 words.":"Ouvrez la salle. Envoyez un message qui mentionne les deux : `@researcher` vérifie que les puces collent encore aux sources ; `@writer` garde le brief sous 200 mots.","Watch up to three rounds. Note who replied and who passed. Speaking is optional.":"Regardez jusqu’à trois tours. Notez qui a répondu et qui a passé. Parler est optionnel.","If the row shows **needs you**, a Bot escalated with `@user`. Answer once, or stop the room. Do not add a third Bot yet.":"Si la ligne montre **needs you**, un Bot a escaladé avec `@user`. Répondez une fois, ou arrêtez la salle. N’ajoutez pas encore un troisième Bot.","Stretch — a Bot that specifies other Bots":"Extension — un Bot qui spécifie d’autres Bots","Optional. One operator’s idea is a Bot used only to specify the next specialist from the work in front of you. In this lab the HR Bot writes the spec; **you** still click New Agent.":"Optionnel. L’idée d’un opérateur : un Bot qui ne sert qu’à spécifier le prochain spécialiste d’après le travail sous les yeux. Dans ce lab le Bot RH écrit la spec ; **vous** cliquez encore New Agent.","Bot HR: specify the next specialist from the project’s needs. You still hire. Video plays on X.":"Bot RH : spécifier le prochain spécialiste d’après les besoins du projet. Vous embauchez encore. La vidéo se joue sur X.","Optional: New Agent `hr`. Short soul: “You specify specialists. You do not run their tools. Output name, title, description, soul sketch (12–20 lines), tools to enable, tools to disable.”":"Optionnel : New Agent `hr`. Âme courte : « Tu spécifies des spécialistes. Tu n’exécutes pas leurs outils. En sortie : name, title, description, croquis d’âme (12–20 lignes), outils à activer, outils à désactiver. »","Ask hr, with `briefing.md` in context: “What third specialist would help next, and what must they never do?”":"Demandez à hr, avec `briefing.md` en contexte : « Quel troisième spécialiste aiderait ensuite, et que ne doit-il jamais faire ? »","You create that Bot in New Agent from the spec. Log it in `bot-roster.md`. Skip this stretch if two Bots already earned the outcome.":"Vous créez ce Bot dans New Agent d’après la spec. Notez-le dans `bot-roster.md`. Sautez cette extension si deux Bots ont déjà gagné le résultat.","Do not give `hr` a mandate to create profiles unattended unless you already know the profile CLI and want that risk. Spec → you hire is the course default.":"Ne donnez pas à `hr` le mandat de créer des profils sans vous, sauf si vous connaissez déjà le CLI des profils et que vous voulez ce risque. Spec → vous embauchez : c’est le défaut du cours.","Check yourself":"Vérifiez-vous","What is a Bot in Hermes Desktop?":"Qu’est-ce qu’un Bot dans Hermes Desktop ?","A Telegram gateway with a different token":"Une passerelle Telegram avec un autre token","A named profile in the roster — own soul, memory, skills, chat":"Un profil nommé dans le roster — propre âme, mémoire, skills, chat","A new product, separate from profiles":"Un nouveau produit, distinct des profils","A sub-agent that dies when the session ends":"Un sous-agent qui meurt à la fin de la session","A Bot is a profile. Bot Mode is a UI plus a messaging protocol over that primitive. `hermes -p researcher chat` is the same agent.":"Un Bot est un profil. Bot Mode est une interface plus un protocole de messages sur cette primitive. `hermes -p researcher chat` est le même agent.","Researcher has web fetch. Should writer also have it?":"Le chercheur a le fetch web. Le rédacteur devrait-il l’avoir aussi ?","Yes — more tools are always better":"Oui — plus d’outils c’est toujours mieux","Yes — otherwise it cannot draft":"Oui — sinon il ne peut pas rédiger","No — least tools; a writer with fetch will invent a research job":"Non — le moins d’outils ; un rédacteur avec fetch s’inventera un job de recherche","Only if they share MEMORY.md":"Seulement s’ils partagent MEMORY.md","Specialization is the point. Shared notes (vault, AGENTS.md) are the company brain. Tools stay narrow.":"La spécialisation est le point. Les notes partagées (coffre, AGENTS.md) sont le cerveau de l’entreprise. Les outils restent étroits.","You type @researcher in the writer chat. When does the reply arrive?":"Vous tapez @researcher dans le chat du rédacteur. Quand arrive la réponse ?","Instantly, interrupting the researcher’s current turn":"Tout de suite, en interrompant le tour en cours du chercheur","Never — @mentions are display-only":"Jamais — les @mentions sont seulement de l’affichage","Later, in the researcher’s Bot Chat — fire-and-forget":"Plus tard, dans le Bot Chat du chercheur — fire-and-forget","Only if both Bots share one model pin":"Seulement si les deux Bots partagent la même épingle de modèle","Delivery is per-invocation. The sending Bot composes its own message. Live interrupt of a Bot mid-turn is future work.":"La livraison est par invocation. Le Bot qui envoie compose son propre message. Interrompre un Bot en plein tour est du travail futur.","The receipt":"Le reçu","Copy the sample into your notes. Paths, not tokens. You are done when the checklist is true **and** `briefing.md` opens without Hermes.":"Copiez l’exemple dans vos notes. Des chemins, pas des tokens. Vous avez fini quand la checklist est vraie **et** que `briefing.md` s’ouvre sans Hermes.","Two Bots exist (`researcher`, `writer`) and each stated hard limits in its own soul":"Deux Bots existent (`researcher`, `writer`) et chacun a énoncé des limites dures dans sa propre âme","Writer does **not** have web fetch":"Le rédacteur n’a **pas** le fetch web","One @mention handoff produced `briefing.md` I opened offline":"Une passation @mention a produit `briefing.md` que j’ai ouvert hors-ligne","`bot-roster.md` names both harnesses (no secrets pasted)":"`bot-roster.md` nomme les deux harness (aucun secret collé)","bot-roster.md (blank)":"bot-roster.md (vide)"}')},58231,e=>{"use strict";let t=e.i(40324).default,s=(e,s)=>({en:e,fr:s??t[e]??e}),o={title:s("Harness Labs"),tagline:s("Drills after mastery — not a second install course."),description:s("Five optional drills after My First AI Agent Part I: rotate a key, break the harness on purpose, measure the empty-session budget, try the Kanban plugin, and run a Bot Mode roster. Not a second install course."),href:"/forge/course/my-first-ai-agent/labs/",courseHref:"/forge/course/my-first-ai-agent/"},a={kicker:s("After mastery · not a second course"),assumesLabel:s("Assumes"),assumesBody:s("Hermes is already installed and chatting (My First AI Agent Part I). Course default is **Hermes Desktop** from mastery 03 — profile + SOUL exist; several drills open the Desktop cockpit. Labs do not re-teach install, BotFather from zero, or vault setup. CLI-only is fine if you can map the same proofs. If anything is missing, open the mastery modules first."),courseCta:s("My First AI Agent course →"),startMastery:s("Start mastery Part I"),glance:s("Mastery vs labs"),glanceBlurb:s("Pedagogy lives in My First AI Agent. Labs only drill and produce artifacts."),requires:s("Requires"),afterPartI:s("After Part I"),afterPartII:s("After Part II"),advanced:s("Advanced"),threeLayers:s("Three layers"),masteryLayer:s("Mastery"),masteryDetail:s("Teach · proofs · install first"),labsLayer:s("Labs"),labsDetail:s("Drills · artifacts after Part I"),skillsLayer:s("Skills"),skillsDetail:s("Curated packages · enable few")},r=[{id:"api-key-hygiene",slug:"api-key-hygiene",number:"01",title:"Key rotation drill",subtitle:"You already know what a key is (Harness 01/03). Prove rotation and no secrets in git.",minutes:20,level:"after-part-i",tags:["OpSec","Keys"],requires:"Hermes running with at least one provider key",assumes:"You understand .env from mastery; this is audit + rotate practice.",ifNotHref:"/forge/course/my-first-ai-agent/03/",ifNotLabel:"Harness 03 — Install",outcome:"keys-audit.md lists providers and secret locations; one key rotated and retested; git status clean of .env.",sections:[{heading:"Rules (reminder only)",bullets:["Secrets only in env / secure store — never SOUL, MEMORY, briefs, or git","Rotate on any chat/log leak","Dev vs prod keys when the provider allows"],callout:"If a key hit chat, rotate now. Editing history is not revocation.",calloutVariant:"warning"},{heading:"Drill",steps:["List every provider in keys-audit.md with where the secret lives.","Move any secret that lives in a markdown note into env; rotate that key.","Rotate the least-critical key on purpose; update Hermes; one successful chat.","Confirm .env is gitignored in repos Hermes can write; git status."]}]},{id:"failure-studio",slug:"failure-studio",number:"02",title:"Failure studio",subtitle:"Break it on purpose: doctor, logs, stuck approvals, bad tool loops — then fix.",minutes:30,level:"after-part-i",tags:["Ops","Debug","Security"],requires:"My First AI Agent Part I (Hermes chats; gateway optional)",assumes:"Desktop or CLI install works on a good day; you have not turned YOLO on for the course.",ifNotHref:"/forge/course/my-first-ai-agent/03/",ifNotLabel:"Harness 03 — Install",outcome:"failure-log.md with three forced failures, what you saw (logs/UI), and the fix for each. No secrets pasted.",sections:[{heading:"Why this lab exists",paragraphs:["Mastery teaches the happy path. Production is the unhappy path: wrong key, hung approval, agent looping tools, gateway silent. This lab forces three failures so doctor and logs become muscle memory — not panic search."],links:[{label:"Harness 10 — Security dials",href:"/forge/course/my-first-ai-agent/10/"},{label:"Harness 06 — First agency",href:"/forge/course/my-first-ai-agent/06/"}]},{heading:"Safety rules",bullets:["Do this on a non-production profile if you have one.","Never paste API keys or bot tokens into failure-log.md.","Do not open WAN ports or disable allowlist “to reproduce.”","Stop if you are about to run destructive shell on real data — use a throwaway folder."],calloutVariant:"warning",callout:"Goal is observability, not bricking the host. If chat dies completely, reinstall path is mastery 03 — not this lab."},{heading:"Failure A — provider / auth smoke",steps:["With Hermes working, temporarily break model auth (wrong key in a throwaway env, or disable the active provider in UI). Do not commit the bad key.","Send a one-line chat. Capture the error surface (UI message or hermes logs snippet redacted).","Run hermes doctor (or Desktop health) if available. Note what it caught vs what it missed.","Restore the good key. Confirm chat works. Log A in failure-log.md."]},{heading:"Failure B — approval stuck",steps:["Set approvals to manual (or ensure a dangerous tool will prompt).","Ask for a tool action that needs approval. Leave it unanswered for 30–60s (or until timeout if shorter).","Note timeout / deny behavior. Approve or cancel deliberately.","Log B: approval mode, what the UI showed, final outcome."]},{heading:"Failure C — tool thrash / bad path",steps:["Ask the agent to write a file to a path that does not exist or is outside the allowed workspace (safe denial expected).","If it loops retries, stop the run after 2–3 cycles. Prefer “stop / cancel” over force-kill unless hung.","Find logs or session transcript. Redact paths if sensitive. Note how you stopped the loop.","Log C with one sentence on how you will scope tools next time."]},{heading:"failure-log.md template",callout:`# failure-log.md
Date / profile: [...]
A Auth: error seen \xb7 doctor said \xb7 fix
B Approval: mode \xb7 timeout \xb7 fix
C Tool thrash: prompt \xb7 stop method \xb7 fix
Secrets: none pasted
`,calloutVariant:"note"}]},{id:"prompt-budget",slug:"prompt-budget",number:"03",title:"Prompt budget audit",subtitle:"Measure fixed empty-session cost; cut tools and skills; re-measure.",minutes:20,level:"after-part-i",tags:["Cost","Tools","Skills"],requires:"My First AI Agent 06; better after 09 skills",assumes:"Primary model works. You can open Tools and Skills panels (or CLI hermes tools / hermes skills).",ifNotHref:"/forge/course/my-first-ai-agent/06/",ifNotLabel:"Harness 06 — First agency",outcome:"prompt-budget.md with before/after prompt-size (or Desktop audit) and two concrete cuts (toolset and/or skill).",sections:[{heading:"Why this lab",paragraphs:["Empty sessions still load system prompt, skills index, memory snapshots, tool schemas, and AGENTS.md. Upgrading the model will not fix a bloated fixed budget. This lab measures and cuts."],links:[{label:"Harness 06 — Spend / fixed cost",href:"/forge/course/my-first-ai-agent/06/"},{label:"Harness 09 — Skills",href:"/forge/course/my-first-ai-agent/09/"}]},{heading:"Audit",steps:["Run hermes prompt-size (offline OK) or the Desktop prompt-budget / context audit if labeled differently. Record total and top slices in prompt-budget.md.","List enabled toolsets. Disable one you never use for this profile (hermes tools or Desktop Tools).","List skills. Uninstall or disable one “for later” skill.","Re-run the audit. Write before → after numbers.","One-line chat: confirm the agent still works for a simple task."],callout:"Do not delete SOUL or MEMORY to win the audit. Cut unused tools and skills first.",calloutVariant:"note"},{heading:"prompt-budget.md template",callout:`# prompt-budget.md
Before: total […] \xb7 top slices: tools […] skills […] memory […]
Cuts: toolset […] \xb7 skill […]
After: total […]
Still works: yes/no
`,calloutVariant:"note"}]},{id:"kanban-board",slug:"kanban-board",number:"04",title:"Kanban multi-profile",subtitle:"Enable the official Desktop Kanban plugin; run one card across profiles.",minutes:30,level:"advanced",tags:["Desktop","Multi-agent","Plugin"],requires:"My First AI Agent Part I; two profiles with SOUL optional but recommended",assumes:"Desktop chat works on at least one profile. You are not installing Hermes here.",ifNotHref:"/forge/course/my-first-ai-agent/04/",ifNotLabel:"Harness 04 — Soul pack",outcome:"kanban-notes.md: plugin enabled, one card moved through columns, which profile ran which step, screenshot optional (no secrets).",sections:[{heading:"Why this lab",paragraphs:["Kanban is the first official Hermes Desktop plugin: board UI, sidebar, hotkeys, backend. It is multi-step / multi-profile work — growth after a solid single harness, not Part I."],tweet:{id:"2083421808385307115",author:"@tonbistudio",href:"https://x.com/tonbistudio/status/2083421808385307115",caption:"The Kanban board in use. Video plays on X.",poster:"/courses/open-harness/citations/2083421808385307115.jpg",posterWidth:1200,posterHeight:675,hasVideo:!0},links:[{label:"Harness 12 — Own it forever",href:"/forge/course/my-first-ai-agent/12/"},{label:"Desktop plugin SDK",href:"https://hermes-agent.nousresearch.com/docs/developer-guide/desktop-plugin-sdk"}]},{heading:"Enable and run",steps:["In Desktop, open Plugins (or Extensions). Enable Kanban if not already on. Restart Desktop if required.","Confirm a Kanban page or sidebar entry appears.","Create one real-ish task card (e.g. “Draft weekly notes outline”). Keep scope small.","If you have two profiles: assign steps so each profile handles a different stage (research vs draft). If one profile only: run the board end-to-end on that profile and note “single profile” in kanban-notes.md.","Move the card through at least two columns. Capture which agent/profile acted.","Write kanban-notes.md: enable path, columns used, profile map, one friction note."],callout:"Do not open the board to untrusted users. Same allowlist discipline as gateway. Plugins extend trust surface.",calloutVariant:"warning"},{heading:"kanban-notes.md template",callout:`# kanban-notes.md
Plugin enabled: how […]
Card: […]
Columns: […]
Profiles: […]
Friction / next: […]
`,calloutVariant:"note"}]},{id:"bot-mode-roster",slug:"bot-mode-roster",number:"05",title:"Bot Mode roster",subtitle:"Turn two souls into named Bots, give each a harness, run one @mention handoff, and keep a file receipt.",minutes:40,level:"advanced",tags:["Desktop","Multi-agent","Bot Mode"],requires:"My First AI Agent Part I; Desktop with a Bots tab (on by default in current builds). Souls from Harness 04.",assumes:"Desktop chat already works. You have pasted a soul into a profile. Bot Mode is the Bots tab next to Sessions — not a second Hermes install.",ifNotHref:"/forge/course/my-first-ai-agent/04/",ifNotLabel:"Harness 04 — Soul pack",outcome:"bot-roster.md names two Bots and their harness (soul, model, skills, tools, memory, face); one @mention handoff produced briefing.md you can open offline.",sections:[{heading:"Why this lab",paragraphs:["Harness 04 taught one profile, one soul. Bot Mode is the Desktop roster for those same profiles."]}]}],i={id:"bot-mode-roster",slug:"bot-mode-roster",number:"05",part:2,title:s("Bot Mode roster"),subtitle:s("Turn two souls into named Bots, give each a harness, run one @mention handoff, and keep a file receipt."),minutes:40,visualPlacement:"none",proof:s("You can say, in plain words: a Bot is a named profile; each specialist gets a harness (soul, model, tools); @mentions are fire-and-forget; you stay the operator. `bot-roster.md` names two Bots; `briefing.md` opens offline."),sections:[{heading:s("How to read this lab"),blocks:[{k:"p",text:s("This is a **drill**, not a thirteenth lesson. You already have a profile and a soul (Harness 04). Read the four cards, then do Drill A and Drill B. Group chat and the stretch are extra.")},{k:"list",items:[s("Come back to a card when Desktop names that word (Bots tab, @mention, group)."),s("Proof is a file you open offline — chat alone is not the receipt.")]},{k:"figure",variant:"lab-bot-mode-roster"}]},{heading:s("Why this lab"),blocks:[{k:"p",text:s("Harness 04 taught one profile, one soul. Bot Mode is the Desktop roster for those same profiles: a name, a face, a pinned model, isolated memory, and a way for Bots to pass work with @mentions. Build a specialist once; it is still there next week.")},{k:"p",text:s("This is not a marketing department and not a second product. You stay the operator. Delivery between Bots is fire-and-forget: the teammate answers in its own Bot Chat when it next runs.")},{k:"tweet",id:"2089471953472020757",author:"@witcheer",href:"https://x.com/witcheer/status/2089471953472020757",caption:s("Bot Mode docs: create, harness, avatars, routines, group chats, @mentions. Video plays on X."),poster:"/courses/open-harness/citations/2089471953472020757.jpg",posterWidth:1199,posterHeight:674,hasVideo:!0},{k:"links",items:[{label:s("Official Bot Mode docs"),href:"https://hermes-agent.nousresearch.com/docs/user-guide/bot-mode"},{label:s("Harness 04 — Soul pack"),href:"/forge/course/my-first-ai-agent/04/"},{label:s("Lab: Kanban multi-profile"),href:"/forge/course/my-first-ai-agent/labs/kanban-board/"}]}]},{heading:s("Core words"),blocks:[{k:"p",text:s("Four lines name almost everything in this drill. The rest is how you click it.")},{k:"lexicon",cards:[{term:s("Bot"),body:s("A named Hermes profile in the Desktop roster: own soul, model, memory, skills, and chat. Files still live under `~/.hermes/profiles/<name>/`."),remember:s("Bot = named profile. Not a Telegram gateway. Not a new product.")},{term:s("Harness (per Bot)"),body:s("The six knobs this specialist is allowed: soul, model pin, skills, tools, memory, face. Shared notes are the company brain; MEMORY.md stays per Bot."),remember:s("Least tools per Bot. Writer without web if researcher fetches.")},{term:s("Canonical Bot Chat"),body:s("The forever-chat created when the Bot is born. `/new` there compacts context; it does not fork a new relationship."),remember:s("One Bot, one canonical chat.")},{term:s("@mention / handoff"),body:s("Type `@researcher have a look`. The sending Bot composes its own message. Delivery is fire-and-forget: the reply lands later in the teammate’s Bot Chat."),remember:s("Handoff, not a live interrupt. You stay the operator.")}]}]},{heading:s("A Bot is a profile"),blocks:[{k:"p",text:s("There is no new primitive. The Bots tab is a UI over profiles you already made. CLI parity: `hermes -p researcher chat` is the same agent. If you ran the Kanban lab, those profiles are already Bots — give them faces and a handoff.")},{k:"list",items:[s("**New Agent** is three fields (Name, Title, Description). Advanced opens clone, model pin, SOUL.md, and per-skill / per-toolset ticks."),s("Routines are ordinary cron jobs named `[bot:<name>] …` — they also show in `hermes cron list`."),s("If the Bots tab is missing: Settings → Plugins → Bots, then a current Desktop build. The old standalone plugin repo is archived.")]},{k:"callout",variant:"note",text:s("Hide a Bot you are not using (right-click → Hide Bot). Delete only when sure. The default profile cannot be deleted.")}]},{heading:s("The harness (six knobs)"),blocks:[{k:"p",text:s("Packaging is cheap. The moat is what you put in: soul, examples of good, voice rules, and which tools this specialist may touch. Do not clone a seven-Bot “team” on day one.")},{k:"table",headers:[s("Knob"),s("What you set"),s("This lab")],rows:[[s("Role"),s("SOUL.md — identity, style, avoid, defaults, hard limits"),s("Analyst (Iris) / Writer (Quill)")],[s("Model"),s("Pin cheap/fast for throughput; stronger for draft. Inherit if one provider."),s("Pin if you can; else inherit")],[s("Skills"),s("Only the howtos this specialist runs"),s("Skip bundled noise")],[s("Tools"),s("Least privilege"),s("Researcher: web. Writer: no fetch")],[s("Memory"),s("What this Bot remembers across jobs"),s("Not secrets in SOUL")],[s("Face"),s("Blob / geometric / upload / AI portrait / pixel pet"),s("Pick one each")]]},{k:"tweet",id:"2090179914461016276",author:"@shannholmberg",href:"https://x.com/shannholmberg/status/2090179914461016276",caption:s("One Bot per vertical, each with its own harness — start with two, not seven."),poster:"/courses/open-harness/citations/2090179914461016276.jpg",posterWidth:1380,posterHeight:1180},{k:"callout",variant:"quote",text:s("One job per Bot, then a handoff. Tighten from there.")}]},{heading:s("Safety rules"),blocks:[{k:"list",items:[s("Approvals stay **manual**. Do not turn YOLO on for this lab."),s("Least tools. A writer with web fetch will invent a research job."),s("No secrets in SOUL, MEMORY, `briefing.md`, or `bot-roster.md`. Shared OAuth is the default — do not paste keys to “give a Bot access.”"),s("Group chats cap at 2–6 Bots and three serial rounds. If a Bot `@user`s you, that is a judgment call — answer or stop.")]},{k:"callout",variant:"warning",text:s("You are still the operator. A roster with @mentions is a handoff protocol, not a department that runs while you sleep.")}]},{heading:s("Drill A — hire two specialists"),blocks:[{k:"steps",id:"bot-mode-a",items:[{title:s("Open Hermes Desktop. Confirm a **Bots** tab next to Sessions. If missing: Settings → Plugins → Bots, restart.")},{title:s("New Agent: name `researcher`, title Research analyst, description “Sourced bullets only. Label speculation. Never invent citations.”")},{title:s("Advanced: paste the Analyst (Iris) soul from Harness 04. Enable only the web/search tools this Bot needs.")},{title:s("Give it a blob or geometric face. Pin a cheap/fast model if you have a second provider; otherwise inherit.")},{title:s("New Agent: name `writer`, title Drafting specialist. Paste the Writer (Quill) soul. **Disable web fetch.** Pin a stronger model if you have one.")},{title:s("Open each Bot Chat. Ask: “Who are you and what are your hard limits?” Confirm they answer in that soul.")}]}]},{heading:s("Drill B — one @mention handoff"),blocks:[{k:"steps",id:"bot-mode-b",items:[{title:s("Pick one real topic you already care about (a book, a local issue, a product you use). Write it in `bot-roster.md`.")},{title:s("In the writer Bot Chat, type: `@researcher five sourced bullets on [topic]. No invented citations.` Wait — the reply is not instant.")},{title:s("When the bullets land: `@writer 150–200 words in my voice from those bullets. Flag unsourced claims. Write briefing.md in my notes folder. Do not send.`")},{title:s("Open `briefing.md` offline. If it exists only inside the chat, ask writer to write the file with an absolute path you control.")},{title:s("In `bot-roster.md`, record: who spoke, which chat the reply appeared in, and whether there was a delay (fire-and-forget is expected).")}]},{k:"callout",variant:"note",text:s("The composer’s `@` autocomplete resolves against the live roster. Your text is not forwarded verbatim. An unknown `@` (or an email) passes through untouched.")}]},{heading:s("Drill C — group chat"),blocks:[{k:"steps",id:"bot-mode-c",items:[{title:s("Right-click a local Bot → Manage groups (or New Group Chat). Seat only `researcher` and `writer`.")},{title:s("Open the room. Send one message that mentions both: `@researcher` check the bullets still match the sources; `@writer` keep the brief under 200 words.")},{title:s("Watch up to three rounds. Note who replied and who passed. Speaking is optional.")},{title:s("If the row shows **needs you**, a Bot escalated with `@user`. Answer once, or stop the room. Do not add a third Bot yet.")}]}]},{heading:s("Stretch — a Bot that specifies other Bots"),blocks:[{k:"p",text:s("Optional. One operator’s idea is a Bot used only to specify the next specialist from the work in front of you. In this lab the HR Bot writes the spec; **you** still click New Agent.")},{k:"tweet",id:"2089583590028009610",author:"@tonbistudio",href:"https://x.com/tonbistudio/status/2089583590028009610",caption:s("Bot HR: specify the next specialist from the project’s needs. You still hire. Video plays on X."),poster:"/courses/open-harness/citations/2089583590028009610.jpg",posterWidth:1200,posterHeight:675,hasVideo:!0},{k:"steps",id:"bot-mode-hr",items:[{title:s("Optional: New Agent `hr`. Short soul: “You specify specialists. You do not run their tools. Output name, title, description, soul sketch (12–20 lines), tools to enable, tools to disable.”")},{title:s("Ask hr, with `briefing.md` in context: “What third specialist would help next, and what must they never do?”")},{title:s("You create that Bot in New Agent from the spec. Log it in `bot-roster.md`. Skip this stretch if two Bots already earned the outcome.")}]},{k:"callout",variant:"warning",text:s("Do not give `hr` a mandate to create profiles unattended unless you already know the profile CLI and want that risk. Spec → you hire is the course default.")}]},{heading:s("Check yourself"),blocks:[{k:"quiz",quiz:{question:s("What is a Bot in Hermes Desktop?"),options:[s("A Telegram gateway with a different token"),s("A named profile in the roster — own soul, memory, skills, chat"),s("A new product, separate from profiles"),s("A sub-agent that dies when the session ends")],correct:s("A named profile in the roster — own soul, memory, skills, chat"),explain:s("A Bot is a profile. Bot Mode is a UI plus a messaging protocol over that primitive. `hermes -p researcher chat` is the same agent.")}},{k:"quiz",quiz:{question:s("Researcher has web fetch. Should writer also have it?"),options:[s("Yes — more tools are always better"),s("Yes — otherwise it cannot draft"),s("No — least tools; a writer with fetch will invent a research job"),s("Only if they share MEMORY.md")],correct:s("No — least tools; a writer with fetch will invent a research job"),explain:s("Specialization is the point. Shared notes (vault, AGENTS.md) are the company brain. Tools stay narrow.")}},{k:"quiz",quiz:{question:s("You type @researcher in the writer chat. When does the reply arrive?"),options:[s("Instantly, interrupting the researcher’s current turn"),s("Never — @mentions are display-only"),s("Later, in the researcher’s Bot Chat — fire-and-forget"),s("Only if both Bots share one model pin")],correct:s("Later, in the researcher’s Bot Chat — fire-and-forget"),explain:s("Delivery is per-invocation. The sending Bot composes its own message. Live interrupt of a Bot mid-turn is future work.")}}]},{heading:s("The receipt"),blocks:[{k:"p",text:s("Copy the sample into your notes. Paths, not tokens. You are done when the checklist is true **and** `briefing.md` opens without Hermes.")},{k:"copycards",items:[{src:"/courses/open-harness/samples/bot-roster.example.md",title:"bot-roster.md",why:"Filled example — copy into your notes folder"}]},{k:"checklist",id:"bot-mode-receipt",items:[s("Two Bots exist (`researcher`, `writer`) and each stated hard limits in its own soul"),s("Writer does **not** have web fetch"),s("One @mention handoff produced `briefing.md` I opened offline"),s("`bot-roster.md` names both harnesses (no secrets pasted)")]},{k:"code",block:{label:s("bot-roster.md (blank)"),lang:"md",code:`# bot-roster.md
Date / host: […]
Topic: […]

## researcher
Title: […]
Soul: Analyst (Iris) / other […]
Model pin: […] or inherit
Tools on: […]
Tools off: […]
Face: blob / geometric / other
Hard limits (quoted from chat): […]

## writer
Title: […]
Soul: Writer (Quill) / other […]
Model pin: […] or inherit
Tools on: […]
Tools off: web fetch (required for this lab)
Face: […]
Hard limits (quoted from chat): […]

## Handoff
@researcher → @writer: yes/no
Reply landed in: writer Bot Chat / group / other […]
Delay / fire-and-forget: […]
briefing.md path (offline open): […]
`}},{k:"refs",primary:[{label:s("Official Bot Mode docs"),href:"https://hermes-agent.nousresearch.com/docs/user-guide/bot-mode"}]}]}]};r.map(e=>(function(e){let t;if("bot-mode-roster"===e)return i;let o=r.find(t=>t.slug===e);return o?(t=o.sections.map((e,t)=>{let a=e.steps?.map(e=>({title:s(e)}));return{heading:s(e.heading),blocks:[...0===t?[{k:"figure",variant:`lab-${o.slug}`}]:[],...(e.paragraphs??[]).map(e=>({k:"p",text:s(e)})),...e.bullets?[{k:"list",items:e.bullets.map(e=>s(e))}]:[],...a?[{k:"steps",id:`${o.slug}-${t}-steps`,items:a}]:[],...e.callout?[{k:"callout",text:s(e.callout),variant:e.calloutVariant}]:[],...e.tweet?[{k:"tweet",id:e.tweet.id,author:e.tweet.author,href:e.tweet.href,caption:e.tweet.caption?s(e.tweet.caption):void 0,poster:e.tweet.poster,posterWidth:e.tweet.posterWidth,posterHeight:e.tweet.posterHeight,hasVideo:e.tweet.hasVideo}]:[],...e.links?[{k:"links",items:e.links.map(e=>({label:s(e.label),href:e.href}))}]:[]]}}),{id:o.id,slug:o.slug,number:o.number,part:2,title:s(o.title),subtitle:s(o.subtitle),minutes:o.minutes,proof:s(o.outcome),visualPlacement:"none",sections:t}):void 0})(e.slug)),s("Harness Labs"),s("All labs"),s("Open Design"),e.s(["HARNESS_LABS",0,r,"HARNESS_LABS_META",0,o,"LABS_INDEX_COPY",0,a,"labsT",0,function(e,s){return"fr"===s?t[e]??e:e}])}]);